  "эффект 1": "effect 1", "эффект 1, мс": "effect 1, ms", "эффект 1: длительность за уровень": "effect 1: duration per level",
  "эффект 1: длительность, мс, база": "effect 1: duration, ms, base", "эффект 1: значение за уровень": "effect 1: value per level", "эффект 1: значение, база": "effect 1: value, base",
